BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_department" ("id" varchar(50) NOT NULL PRIMARY KEY, "departmentName" varchar(100) NOT NULL, "departmentCode" varchar(50) NOT NULL UNIQUE, "parentDepartmentId" varchar(50) NULL, "departmentHeadId" varchar(50) NULL, "trackingEnabled" bool NOT NULL, "kpiCategory" text NOT NULL CHECK ((JSON_VALID("kpiCategory") OR "kpiCategory" IS NULL)), "activeStatus" bool NOT NULL);
CREATE TABLE "core_document" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "fileUrl" text NOT NULL, "uploadDate" datetime NOT NULL, "fileType" varchar(50) NULL, "status" varchar(50) NOT NULL, "uploadedBy_id" varchar(50) NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_employee" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL UNIQUE, "fullName" varchar(200) NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "mobileNumber" varchar(20) NOT NULL, "password" varchar(128) NOT NULL, "profilePhoto" text NULL, "designation" varchar(100) NOT NULL, "reportingManager" varchar(50) NULL, "employmentType" varchar(50) NOT NULL, "workMode" varchar(50) NOT NULL, "joiningDate" date NOT NULL, "trackingEnabled" bool NOT NULL, "attendanceRequired" bool NOT NULL, "taskAssignmentAllowed" bool NOT NULL, "accountStatus" bool NOT NULL, "departmentId_id" varchar(50) NULL REFERENCES "core_department" ("id") DEFERRABLE INITIALLY DEFERRED, "roleId_id" varchar(50) NULL REFERENCES "core_role" ("id") DEFERRABLE INITIALLY DEFERRED, "statusId_id" varchar(50) NULL REFERENCES "core_statusmaster" ("id") DEFERRABLE INITIALLY DEFERRED, "travelMode" varchar(50) NOT NULL);
CREATE TABLE "core_permissionrequest" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "description" text NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL, "approver_id" varchar(50) NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED, "requester_id" varchar(50) NOT NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_project" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "description" text NULL, "endDate" date NULL, "startDate" date NULL, "updatedAt" datetime NOT NULL, "projectType" varchar(50) NOT NULL);
CREATE TABLE "core_project_assignedEmployees" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "project_id" char(32) NOT NULL REFERENCES "core_project" ("id") DEFERRABLE INITIALLY DEFERRED, "employee_id" varchar(50) NOT NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_registrationrequest" ("fullName" varchar(200) NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "mobileNumber" varchar(20) NOT NULL, "password" varchar(128) NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "core_reportingmanager" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "employeeName" varchar(200) NOT NULL, "managerId" varchar(50) NOT NULL, "managerName" varchar(200) NOT NULL, "reportingType" varchar(50) NOT NULL, "effectiveFrom" varchar(50) NOT NULL, "effectiveTo" varchar(50) NULL, "visibilityScope" varchar(50) NOT NULL, "overrideAccess" bool NOT NULL);
CREATE TABLE "core_role" ("id" varchar(50) NOT NULL PRIMARY KEY, "roleName" varchar(100) NOT NULL, "roleCode" varchar(50) NOT NULL UNIQUE, "roleType" varchar(50) NOT NULL, "defaultDashboard" varchar(100) NOT NULL, "rolePriority" integer NOT NULL, "activeStatus" bool NOT NULL);
CREATE TABLE "core_rolepermission" ("id" varchar(50) NOT NULL PRIMARY KEY, "roleName" varchar(100) NOT NULL, "module" varchar(100) NOT NULL, "view" bool NOT NULL, "create" bool NOT NULL, "edit" bool NOT NULL, "delete" bool NOT NULL, "approve" bool NOT NULL, "export" bool NOT NULL, "roleId_id" varchar(50) NOT NULL REFERENCES "core_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_statusmaster" ("id" varchar(50) NOT NULL PRIMARY KEY, "statusName" varchar(100) NOT NULL, "tracking" bool NOT NULL, "visibility" varchar(50) NOT NULL, "activeStatus" bool NOT NULL);
CREATE TABLE "core_task" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "description" text NULL, "status" varchar(50) NOT NULL, "dueDate" date NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL, "project_id" char(32) NULL REFERENCES "core_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_task_assignedEmployees" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "task_id" char(32) NOT NULL REFERENCES "core_task" ("id") DEFERRABLE INITIALLY DEFERRED, "employee_id" varchar(50) NOT NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "crm_customer" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "company" varchar(200) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "territory" varchar(100) NOT NULL, "lastContact" date NULL, "status" varchar(50) NOT NULL);
CREATE TABLE "crm_distributor" ("id" varchar(50) NOT NULL PRIMARY KEY, "distributorId" varchar(50) NOT NULL UNIQUE, "firmName" varchar(200) NOT NULL, "proprietorName" varchar(200) NOT NULL, "mobileNumber" varchar(20) NOT NULL, "emailAddress" varchar(254) NOT NULL, "panProprietor" varchar(50) NOT NULL, "panFirm" varchar(50) NOT NULL, "gstNumber" varchar(50) NOT NULL, "dateOfBirth" date NOT NULL, "marriageAnniversary" date NULL, "officeAddress" text NOT NULL, "currentAddress" text NOT NULL, "permanentAddress" text NOT NULL, "district" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "pincode" varchar(20) NOT NULL, "typeOfFirm" varchar(50) NOT NULL, "distributorProfile" text NOT NULL CHECK ((JSON_VALID("distributorProfile") OR "distributorProfile" IS NULL)), "yearsOfEstablishment" integer NOT NULL, "yearsOfExperience" integer NOT NULL, "topCompaniesAssociated" text NOT NULL CHECK ((JSON_VALID("topCompaniesAssociated") OR "topCompaniesAssociated" IS NULL)), "pesticideLicenseNo" varchar(100) NULL, "seedLicenseNo" varchar(100) NULL, "fertiliserLicenseNo" varchar(100) NULL, "pesticideLicenseExpiry" date NULL, "seedLicenseExpiry" date NULL, "fertiliserLicenseExpiry" date NULL, "godownSpace" integer NOT NULL, "shopSpace" integer NOT NULL, "housePropertyOwned" bool NOT NULL, "computerAvailable" bool NOT NULL, "internetAvailable" bool NOT NULL, "deliveryVehicles" integer NOT NULL, "salesmenAvailable" integer NOT NULL, "bankName" varchar(200) NOT NULL, "accountNumber" varchar(100) NOT NULL, "accountType" varchar(50) NOT NULL, "bankLimitCC" real NOT NULL, "otherLoans" varchar(200) NULL, "totalFundsEmployed" real NOT NULL, "ownInvestment" real NOT NULL, "preferredTransporters" text NOT NULL CHECK ((JSON_VALID("preferredTransporters") OR "preferredTransporters" IS NULL)), "depotLocation" varchar(200) NOT NULL, "attachedRetailersList" text NULL, "numberOfRetailers" integer NOT NULL, "declarationAccepted" bool NOT NULL, "proprietorSignature" text NULL, "witnessDetails" text NOT NULL CHECK ((JSON_VALID("witnessDetails") OR "witnessDetails" IS NULL)), "submittedBy" text NOT NULL CHECK ((JSON_VALID("submittedBy") OR "submittedBy" IS NULL)), "forwardedBy" text NOT NULL CHECK ((JSON_VALID("forwardedBy") OR "forwardedBy" IS NULL)), "approvedBy" text NOT NULL CHECK ((JSON_VALID("approvedBy") OR "approvedBy" IS NULL)), "governmentDocuments" text NOT NULL CHECK ((JSON_VALID("governmentDocuments") OR "governmentDocuments" IS NULL)), "activeStatus" bool NOT NULL);
CREATE TABLE "crm_distributorlink" ("id" varchar(50) NOT NULL PRIMARY KEY, "firmName" varchar(200) NOT NULL, "assignedTerritoryId" varchar(50) NOT NULL, "assignedSalesExecutiveIds" text NOT NULL CHECK ((JSON_VALID("assignedSalesExecutiveIds") OR "assignedSalesExecutiveIds" IS NULL)), "seedLicense" bool NOT NULL, "seedLicenseNumber" varchar(100) NULL, "seedLicenseExpiry" date NULL, "fertiliserLicense" bool NOT NULL, "fertiliserLicenseNumber" varchar(100) NULL, "fertiliserLicenseExpiry" date NULL, "pesticideLicense" bool NOT NULL, "pesticideLicenseNumber" varchar(100) NULL, "pesticideLicenseExpiry" date NULL, "retailerNetworkCount" integer NOT NULL, "retailers" text NOT NULL CHECK ((JSON_VALID("retailers") OR "retailers" IS NULL)), "godownSpace" integer NOT NULL, "shopSpace" integer NOT NULL, "vehicleCount" integer NOT NULL, "hasComputer" bool NOT NULL, "hasInternet" bool NOT NULL, "status" varchar(50) NOT NULL, "statusHistory" text NOT NULL CHECK ((JSON_VALID("statusHistory") OR "statusHistory" IS NULL)), "contactPerson" varchar(200) NULL, "contactPhone" varchar(20) NULL, "contactEmail" varchar(254) NULL, "address" text NULL, "supportingDocuments" text NOT NULL CHECK ((JSON_VALID("supportingDocuments") OR "supportingDocuments" IS NULL)), "distributorId_id" varchar(50) NOT NULL REFERENCES "crm_distributor" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "crm_lead" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "company" varchar(200) NOT NULL, "value" real NOT NULL, "status" varchar(50) NOT NULL, "source" varchar(100) NOT NULL, "createdAt" date NOT NULL);
CREATE TABLE "crm_salesexecutive" ("id" varchar(50) NOT NULL PRIMARY KEY, "fullName" varchar(200) NOT NULL, "role" varchar(100) NOT NULL, "department" varchar(100) NOT NULL, "reportingManagerId" varchar(50) NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "gpsTracking" bool NOT NULL, "workMode" varchar(50) NOT NULL, "status" varchar(50) NOT NULL, "assignedTerritoryIds" text NOT NULL CHECK ((JSON_VALID("assignedTerritoryIds") OR "assignedTerritoryIds" IS NULL)), "employeeId_id" varchar(50) NOT NULL REFERENCES "core_employee" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "crm_salestarget" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "territoryId" varchar(50) NOT NULL, "productCategory" varchar(50) NOT NULL, "targetValue" real NOT NULL, "achievementValue" real NOT NULL, "siteVisits" integer NOT NULL, "feedbackScore" real NOT NULL, "pendingApprovals" integer NOT NULL, "remarks" text NULL, "period" varchar(50) NOT NULL);
CREATE TABLE "crm_territory" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "region" varchar(50) NOT NULL, "district" varchar(100) NOT NULL, "assignedSalesExecutiveId" varchar(50) NULL, "linkedDistributorIds" text NOT NULL CHECK ((JSON_VALID("linkedDistributorIds") OR "linkedDistributorIds" IS NULL)), "coverageArea" varchar(100) NOT NULL, "geoFencing" bool NOT NULL, "status" varchar(50) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "field_tracking_adhocmeeting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "client_name" varchar(255) NOT NULL, "meeting_title" varchar(255) NOT NULL, "meeting_type" varchar(100) NOT NULL, "date" date NOT NULL, "time" time NOT NULL, "location_name" varchar(255) NOT NULL, "priority" varchar(50) NOT NULL, "description" text NULL, "current_lat" decimal NOT NULL, "current_lng" decimal NOT NULL, "destination_lat" decimal NOT NULL, "destination_lng" decimal NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "employee_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "contact_person" varchar(255) NULL, "designation" varchar(255) NULL, "status" varchar(50) NOT NULL, "end_lat" decimal NULL, "end_lng" decimal NULL, "end_time" datetime NULL, "start_lat" decimal NULL, "start_lng" decimal NULL, "start_time" datetime NULL, "distance_km" real NOT NULL, "fuel_approved" bool NOT NULL, "fuel_cost" real NOT NULL, "photo" varchar(100) NULL);
CREATE TABLE "field_tracking_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "event_type" varchar(50) NOT NULL, "description" varchar(255) NOT NULL, "timestamp" datetime NOT NULL, "user_id" integer NULL, "employee_name" varchar(255) NULL);
CREATE TABLE "field_tracking_dailyroute" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "employee_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "field_tracking_routestop" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order_index" integer unsigned NOT NULL CHECK ("order_index" >= 0), "status" varchar(20) NOT NULL, "expected_time" time NULL, "route_id" bigint NOT NULL REFERENCES "field_tracking_dailyroute" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" bigint NOT NULL REFERENCES "field_tracking_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "field_tracking_site" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "address" text NULL, "latitude" decimal NOT NULL, "longitude" decimal NOT NULL, "geofence_radius" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "field_tracking_sitevisitformtemplate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "schema" text NOT NULL CHECK ((JSON_VALID("schema") OR "schema" IS NULL)), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE "field_tracking_visitlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "check_in_time" datetime NOT NULL, "recorded_lat" decimal NOT NULL, "recorded_lng" decimal NOT NULL, "distance_from_site" real NULL, "photo" varchar(100) NULL, "is_verified" bool NOT NULL, "remarks" text NULL, "employee_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" bigint NOT NULL REFERENCES "field_tracking_site" ("id") DEFERRABLE INITIALLY DEFERRED, "report_data" text NULL CHECK ((JSON_VALID("report_data") OR "report_data" IS NULL)), "meeting_id" bigint NULL REFERENCES "field_tracking_adhocmeeting" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_category" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "parentCategory" varchar(50) NULL, "type" varchar(50) NOT NULL, "description" text NULL, "status" varchar(50) NOT NULL, "linkedProducts" integer NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL);
CREATE TABLE "inventory_location" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "type" varchar(50) NOT NULL, "address" text NOT NULL, "geoCoordinates" varchar(100) NULL, "gpsEnabled" bool NOT NULL, "geoFenceEnabled" bool NOT NULL, "gpsRequired" bool NOT NULL, "maxCapacity" real NOT NULL, "currentUtilization" real NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL);
CREATE TABLE "inventory_posalert" ("id" varchar(50) NOT NULL PRIMARY KEY, "terminalId" varchar(50) NOT NULL, "terminalName" varchar(200) NOT NULL, "type" varchar(50) NOT NULL, "message" text NOT NULL, "timestamp" varchar(50) NOT NULL, "resolved" bool NOT NULL);
CREATE TABLE "inventory_posterminal" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "location" varchar(200) NOT NULL, "type" varchar(50) NOT NULL, "status" varchar(50) NOT NULL, "lastSync" varchar(50) NOT NULL, "todayTransactions" integer NOT NULL, "todaySales" real NOT NULL, "errorCount" integer NOT NULL, "ipAddress" varchar(50) NOT NULL, "version" varchar(50) NOT NULL, "operator" varchar(100) NOT NULL);
CREATE TABLE "inventory_product" ("id" varchar(50) NOT NULL PRIMARY KEY, "productId" varchar(50) NOT NULL UNIQUE, "sku" varchar(100) NOT NULL, "barcode" varchar(100) NULL, "name" varchar(200) NOT NULL, "category" varchar(50) NOT NULL, "brand" varchar(100) NOT NULL, "uom" varchar(50) NOT NULL, "sellingPrice" real NOT NULL, "taxCategory" varchar(50) NULL, "trackInventory" bool NOT NULL, "allowDiscount" bool NOT NULL, "serialBatchTracking" bool NOT NULL, "expiryTracking" bool NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL);
CREATE TABLE "inventory_uom" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL, "shortCode" varchar(20) NOT NULL, "conversionFactor" real NOT NULL, "baseUnit" varchar(50) NULL, "isBaseUnit" bool NOT NULL, "inUse" bool NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL);
CREATE TABLE "inventory_vendor" ("id" varchar(50) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "type" varchar(50) NOT NULL, "contactPerson" varchar(200) NOT NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "address" text NOT NULL, "gstId" varchar(50) NOT NULL, "creditLimit" real NOT NULL, "paymentTerms" integer NOT NULL, "linkedWarehouse" varchar(50) NOT NULL, "status" varchar(50) NOT NULL, "createdAt" datetime NOT NULL, "updatedAt" datetime NOT NULL);
CREATE TABLE "ops_alert" ("id" varchar(50) NOT NULL PRIMARY KEY, "type" varchar(50) NOT NULL, "message" text NOT NULL, "timestamp" datetime NOT NULL, "severity" varchar(50) NOT NULL, "resolved" bool NOT NULL, "relatedEntityId" varchar(50) NULL, "relatedEntityType" varchar(50) NULL);
CREATE TABLE "ops_attendanceentry" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeName" varchar(200) NOT NULL, "employeeCode" varchar(50) NOT NULL, "designation" varchar(100) NOT NULL, "date" date NOT NULL, "scheduledShift" varchar(100) NOT NULL, "actualCheckIn" varchar(50) NULL, "actualCheckOut" varchar(50) NULL, "lateArrival" integer NOT NULL, "earlyExit" integer NOT NULL, "totalHoursWorked" real NOT NULL, "status" varchar(50) NOT NULL);
CREATE TABLE "ops_employeetask" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "taskTitle" varchar(200) NOT NULL, "description" text NOT NULL, "assignedDate" date NOT NULL, "deadline" date NOT NULL, "status" varchar(50) NOT NULL, "completionPercent" integer NOT NULL, "proofUploaded" bool NOT NULL, "notes" text NULL, "assignedBy" varchar(50) NOT NULL);
CREATE TABLE "ops_employeewallet" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL UNIQUE, "balance" real NOT NULL, "totalEarned" real NOT NULL, "totalWithdrawn" real NOT NULL);
CREATE TABLE "ops_geofencealert" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeName" varchar(200) NOT NULL, "employeeCode" varchar(50) NOT NULL, "designation" varchar(100) NOT NULL, "currentLocation" varchar(200) NOT NULL, "assignedZone" varchar(200) NOT NULL, "alertType" varchar(50) NOT NULL, "alertTime" varchar(50) NULL, "idleDuration" integer NOT NULL, "planVsActual" real NOT NULL, "status" varchar(50) NOT NULL, "priority" varchar(50) NOT NULL, "resolved" bool NOT NULL);
CREATE TABLE "ops_leavebalance" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "type" varchar(100) NOT NULL, "total" integer NOT NULL, "used" integer NOT NULL, "available" integer NOT NULL);
CREATE TABLE "ops_leaverequest" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "leaveType" varchar(100) NOT NULL, "startDate" date NOT NULL, "endDate" date NOT NULL, "reason" text NOT NULL, "status" varchar(50) NOT NULL, "requestDate" datetime NOT NULL, "managerId" varchar(50) NULL);
CREATE TABLE "ops_meeting" ("id" varchar(50) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "type" varchar(50) NOT NULL, "date" date NOT NULL, "startTime" time NOT NULL, "endTime" time NOT NULL, "organizer" varchar(200) NOT NULL, "organizerId" varchar(50) NOT NULL, "attendees" text NOT NULL CHECK ((JSON_VALID("attendees") OR "attendees" IS NULL)), "externalGuests" text NOT NULL CHECK ((JSON_VALID("externalGuests") OR "externalGuests" IS NULL)), "location" varchar(200) NOT NULL, "mode" varchar(50) NOT NULL, "meetingLink" varchar(200) NULL, "agenda" text NOT NULL, "notes" text NULL, "attachments" text NOT NULL CHECK ((JSON_VALID("attachments") OR "attachments" IS NULL)), "reminder" varchar(50) NOT NULL, "recurring" varchar(50) NOT NULL, "priority" varchar(50) NOT NULL, "approvalRequired" bool NOT NULL, "status" varchar(50) NOT NULL, "isActive" bool NOT NULL);
CREATE TABLE "ops_message" ("id" varchar(50) NOT NULL PRIMARY KEY, "senderId" varchar(50) NOT NULL, "receiverId" varchar(50) NULL, "groupName" varchar(100) NULL, "content" text NOT NULL, "timestamp" datetime NOT NULL, "readBy" text NOT NULL CHECK ((JSON_VALID("readBy") OR "readBy" IS NULL)));
CREATE TABLE "ops_performancemetric" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "metricName" varchar(100) NOT NULL, "value" real NOT NULL, "target" real NOT NULL, "period" varchar(50) NOT NULL);
CREATE TABLE "ops_trackingentry" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "employeeName" varchar(200) NOT NULL, "role" varchar(100) NOT NULL, "currentLocation" varchar(200) NOT NULL, "checkInTime" datetime NOT NULL, "checkOutTime" datetime NULL, "travelDistance" real NOT NULL, "idleTime" real NOT NULL, "planVsActual" real NOT NULL, "status" varchar(50) NOT NULL, "date" date NOT NULL, "reimbursementAmount" real NOT NULL, "routePath" text NOT NULL CHECK ((JSON_VALID("routePath") OR "routePath" IS NULL)), "timeSpentOnSite" real NOT NULL);
CREATE TABLE "ops_withdrawalrequest" ("id" varchar(50) NOT NULL PRIMARY KEY, "employeeId" varchar(50) NOT NULL, "amount" real NOT NULL, "status" varchar(50) NOT NULL, "requestDate" datetime NOT NULL);
